import React from 'react';
import Sidebar from './Sidebar';
import Header from './Header';

interface LayoutProps {
    children: React.ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ children }) => {
    return (
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex transition-colors duration-300">
            {/* Sidebar - Fixed width on Desktop */}
            <aside className="hidden lg:block w-72 flex-shrink-0">
                <Sidebar />
            </aside>

            {/* Mobile Sidebar (handled internally by Sidebar component via fixed positioning) */}
            <div className="lg:hidden">
                <Sidebar />
            </div>

            {/* Main Content Area */}
            <main className="flex-1 w-full min-w-0 flex flex-col pt-16 lg:pt-0">
                {/* Top Header for Utility Items */}
                <Header />

                <div className="flex-1 p-4 lg:p-8 overflow-x-hidden animate-in fade-in duration-500">
                    {children}
                </div>
            </main>
        </div>
    );
};

export default Layout;
